#!/usr/bin/env bash
# Группа CI «selftests-a» — часть slow-набора (маркер slow, не nightly).
# v3.30: группы больше не перечисляют команды по одной. Всё живёт в pytest; разбиение — по маркерам
# и именам, чтобы джобы шли параллельно и примерно равно по времени. Добавленная проверка попадает
# в свою группу сама.
set -euo pipefail
export PYTHONDONTWRITEBYTECODE=1   # байткод в дереве ломает проверку целостности managed
cd "$(dirname "$0")/../.."
# ЗАМЕР ЦЕНЫ (2026-09-07, #465). После снятия 13 тяжёлых интеграционных лумпов с шарда `fast`
# (fast: ~287 c -> ~207 c по факту CI) slow-набор вырос, и по фактическим временам прогона стену
# держал selftests-m (~196 c). Ретюн по замеру:
#   • самый тяжёлый КЛАСТЕР `test_workpackage_*` (w) перенесён СЮДА из группы m;
#   • самый тяжёлый одиночный ФАЙЛ `test_validate_release_claims` (~99 c, ~16 тестов по ~6 c —
#     под loadfile он пришпилен к одному воркеру и в одиночку задаёт пол шарда) не влезает ни в a,
#     ни в m, не пробив стену, поэтому ПРИПАРКОВАН в недогруженной группе `contracts` и ИСКЛЮЧЁН
#     здесь по имени (`and not test_validate_release`), чтобы не гонять дважды.
# По фактическим временам CI это даёт a≈150 c, m≈120–150 c, contracts≈100 c — все под стеной 180 c.
#
# Как работает маршрутизация (важно, иначе «граница по первой букве» обманчива): `-k` матчит
# ПОДСТРОКУ по именам — имени функции/класса И имени файла-модуля. Файл с буквой модуля НЕ из этого
# набора не едет целиком в m: его функции `test_a…test_h`/`test_w` подтягиваются СЮДА поштучно, а
# остальные — в m. То есть многие файлы РАСПАДАЮТСЯ между шардами по имени функции — это заложено в
# исходную схему «по первой букве имени теста», и потому баланс проверяется по фактическим временам
# джоб, а не по буквам файлов. Партиция полная и непересекающаяся: группа m — ровно
# `not (то, что здесь)` (с тем же исключением монолита). Имена CI-контекстов НЕ меняются (пути
# скриптов те же), required-статусы branch protection целы. Границу уточнять по временам прогона.
python3 -m pytest -n auto --dist loadfile tests/ -q -m "slow and not nightly" \
  -k "(test_a or test_b or test_c or test_d or test_e or test_f or test_g or test_h or test_w) and not test_validate_release"
